inline int binOf(double x, const double* e, int n) { int i = 0; while (i + 1 < n && e[i + 1] <= x) ++i; return i; }
inline int slotOf(int now, const int* g, int n) { int i = 0; while (i < n - 1 && g[i] < now) ++i; return i; }
inline double sigm(double z) { if (z > 30) z = 30; if (z < -30) z = -30; return 1.0 / (1.0 + std::exp(-z)); }
inline Read emptyRead(int side) { Read r; r.valid = false; r.side = side; r.pIn = r.pInShow = r.pInTimeOnly = r.afterP = r.byP = NAN;
  r.afterShow = NAN; r.afterQualified = false; r.cellN = 0; r.afterT = r.byT = -1; return r; }
template <int KT, int KD, int KG, int KBD>
inline Read readT(int mso, int side, double distance, double normaliser, double rangeSoFar, int now, int N, int close,
                  double byThr, double afterThr, double afterShow, const double* inE, const double* inD, int nIn,
                  int bNormRange, const double (&te)[KT], const double (&de)[KD],
                  const double (&base)[KT], const double (&P)[KT][KD], const int (&cn)[KT][KD], const int (&grid)[KG],
                  const double (&bde)[KBD], const double (&B)[KG][KBD][KG]) {
  Read r = emptyRead(side);
  if (mso < N || now > grid[KG - 1] || !std::isfinite(distance) || !std::isfinite(normaliser)) return r;
  double x = normaliser > 0 ? distance / normaliser : 0.0;
  int ti = binOf((double)mso, te, KT), di = binOf(x, de, KD);
  r.valid = true; r.pIn = P[ti][di]; r.pInTimeOnly = base[ti]; r.cellN = cn[ti][di];
  { int k = binOf(r.pIn, inE, nIn); double v = r.pIn + inD[k]; r.pInShow = v < 0.01 ? 0.01 : (v > 0.99 ? 0.99 : v); }
  r.afterShow = afterShow;
  double xb = bNormRange ? (rangeSoFar > 0 ? distance / rangeSoFar : 0.0) : x;
  int sl = slotOf(now, grid, KG), bi = binOf(xb, bde, KBD);
  for (int j = sl; j < KG; ++j) if (grid[j] < close && B[sl][bi][j] >= afterThr - 1e-12) { r.afterT = grid[j]; r.afterP = B[sl][bi][j]; r.afterQualified = true; }
  if (!r.afterQualified) { double bp = -1.0; for (int j = sl; j < KG; ++j) if (grid[j] < close && B[sl][bi][j] > bp) { bp = B[sl][bi][j]; r.afterT = grid[j]; r.afterP = bp; } }
  for (int j = sl; j < KG - 1; ++j) if (1.0 - B[sl][bi][j] >= byThr - 1e-12) { r.byT = grid[j]; r.byP = 1.0 - B[sl][bi][j]; break; }
  return r;
}
// every closed RTH bar: hlr::read(market, minutesSinceOpen, side, distance, normaliser, nowMinuteOfDay, rangeSoFar)
inline Read read(int market, int minutesSinceOpen, int side, double distance, double normaliser, int nowMinuteOfDay,
                 double rangeSoFar) {
  switch (market) {
    case ES: return readT(minutesSinceOpen, side, distance, normaliser, rangeSoFar, nowMinuteOfDay, es::kN, kClose[ES],
                           es::kByThr, es::kAfterThr, es::kAfterShow, es::kInEdges, es::kInDelta, 8,
                           es::kBNormRange, es::kTimeEdges, es::kDistEdges, es::kBase,
                           es::kP, es::kCellN, es::kGrid, es::kBDistEdges, es::kB);
    case NQ: return readT(minutesSinceOpen, side, distance, normaliser, rangeSoFar, nowMinuteOfDay, nq::kN, kClose[NQ],
                           nq::kByThr, nq::kAfterThr, nq::kAfterShow, nq::kInEdges, nq::kInDelta, 8,
                           nq::kBNormRange, nq::kTimeEdges, nq::kDistEdges, nq::kBase,
                           nq::kP, nq::kCellN, nq::kGrid, nq::kBDistEdges, nq::kB);
    case CL: return readT(minutesSinceOpen, side, distance, normaliser, rangeSoFar, nowMinuteOfDay, cl::kN, kClose[CL],
                           cl::kByThr, cl::kAfterThr, cl::kAfterShow, cl::kInEdges, cl::kInDelta, 8,
                           cl::kBNormRange, cl::kTimeEdges, cl::kDistEdges, cl::kBase,
                           cl::kP, cl::kCellN, cl::kGrid, cl::kBDistEdges, cl::kB);
    case GC: return readT(minutesSinceOpen, side, distance, normaliser, rangeSoFar, nowMinuteOfDay, gc::kN, kClose[GC],
                           gc::kByThr, gc::kAfterThr, gc::kAfterShow, gc::kInEdges, gc::kInDelta, 8,
                           gc::kBNormRange, gc::kTimeEdges, gc::kDistEdges, gc::kBase,
                           gc::kP, gc::kCellN, gc::kGrid, gc::kBDistEdges, gc::kB);
    case HG: return readT(minutesSinceOpen, side, distance, normaliser, rangeSoFar, nowMinuteOfDay, hg::kN, kClose[HG],
                           hg::kByThr, hg::kAfterThr, hg::kAfterShow, hg::kInEdges, hg::kInDelta, 8,
                           hg::kBNormRange, hg::kTimeEdges, hg::kDistEdges, hg::kBase,
                           hg::kP, hg::kCellN, hg::kGrid, hg::kBDistEdges, hg::kB);
    case NG: return readT(minutesSinceOpen, side, distance, normaliser, rangeSoFar, nowMinuteOfDay, ng::kN, kClose[NG],
                           ng::kByThr, ng::kAfterThr, ng::kAfterShow, ng::kInEdges, ng::kInDelta, 8,
                           ng::kBNormRange, ng::kTimeEdges, ng::kDistEdges, ng::kBase,
                           ng::kP, ng::kCellN, ng::kGrid, ng::kBDistEdges, ng::kB);
    case EU: return readT(minutesSinceOpen, side, distance, normaliser, rangeSoFar, nowMinuteOfDay, eu::kN, kClose[EU],
                           eu::kByThr, eu::kAfterThr, eu::kAfterShow, eu::kInEdges, eu::kInDelta, 8,
                           eu::kBNormRange, eu::kTimeEdges, eu::kDistEdges, eu::kBase,
                           eu::kP, eu::kCellN, eu::kGrid, eu::kBDistEdges, eu::kB);
  }
  return emptyRead(side);
}
template <int KJ, int KTB, int NBL, int NBH>
inline Timing timingT(const double* f, int side, int now, int mso, int close, double q, const int (&e)[KJ + 1],
                      const double (&mu)[kTF], const double (&sd)[kTF], const double (&bL)[NBL], const double (&bH)[NBH]) {
  Timing t; t.valid = false; t.pLater = t.pClose = t.elseMass = NAN; t.elseFrom = t.elseTo = -1;
  double z[kTF];
  for (int k = 0; k < kTF; ++k) { if (!std::isfinite(f[k])) return t; z[k] = (f[k] - mu[k]) / sd[k]; }
  int tb = mso / 30; if (tb < 0) tb = 0; if (tb > KTB - 1) tb = KTB - 1;
  double sL = bL[0] + (tb >= 1 ? bL[tb] : 0.0);
  for (int k = 0; k < kTF; ++k) sL += bL[KTB + k] * z[k] + bL[KTB + kTF + k] * z[k] * side;
  double pl = sigm(sL);
  int c = 0; while (c < KJ - 1 && e[c + 1] < now) ++c;
  double p[KJ]; for (int j = 0; j < KJ; ++j) p[j] = 0.0;
  double surv = 1.0, pc = 0.0;
  for (int j = c; j < KJ; ++j) {
    double ahead = (e[j] - now) / 60.0, cl = (e[j] >= close - 30) ? 1.0 : 0.0;
    double s = bH[0] + (j >= 1 ? bH[j] : 0.0) + bH[KJ] * ahead;
    for (int k = 0; k < kTF; ++k) s += bH[KJ + 1 + k] * z[k] + bH[KJ + 1 + kTF + k] * z[k] * cl + bH[KJ + 1 + 2 * kTF + k] * z[k] * ahead;
    double h = (j == KJ - 1) ? 1.0 : sigm(s);
    p[j] = surv * h * pl; surv *= (1.0 - h);
    if (cl > 0) { pc += p[j]; p[j] = 0.0; }
  }
  t.valid = true; t.pLater = pl; t.pClose = pc;
  double tot = 0.0; for (int j = 0; j < KJ; ++j) tot += p[j];
  if (tot <= 1e-12) return t;
  int ba = -1, bb = -1; double bs = 0.0;
  for (int a = c; a < KJ; ++a) { double s = 0.0;
    for (int b = a; b < KJ; ++b) { s += p[b] / tot;
      if (s >= q - 1e-12) { if (ba < 0 || (b - a) < (bb - ba) || ((b - a) == (bb - ba) && s > bs + 1e-12)) { ba = a; bb = b; bs = s; } break; } } }
  if (ba >= 0) { t.elseFrom = e[ba] > now ? e[ba] : now; t.elseTo = e[bb + 1]; t.elseMass = bs; }
  return t;
}
// the "2nd Time" cell, every closed RTH bar from kMinMinutes: f = the 14 features above
inline Timing timing(int market, const double* f, int side, int nowMinuteOfDay, int minutesSinceOpen, double q = kElseQ) {
  switch (market) {
    case ES: return timingT<es::kJ, es::kTB, 41, 69>(f, side, nowMinuteOfDay, minutesSinceOpen, kClose[ES], q, es::kEdges, es::kMu, es::kSd, es::kBL, es::kBH);
    case NQ: return timingT<nq::kJ, nq::kTB, 41, 69>(f, side, nowMinuteOfDay, minutesSinceOpen, kClose[NQ], q, nq::kEdges, nq::kMu, nq::kSd, nq::kBL, nq::kBH);
    case CL: return timingT<cl::kJ, cl::kTB, 39, 65>(f, side, nowMinuteOfDay, minutesSinceOpen, kClose[CL], q, cl::kEdges, cl::kMu, cl::kSd, cl::kBL, cl::kBH);
    case GC: return timingT<gc::kJ, gc::kTB, 39, 64>(f, side, nowMinuteOfDay, minutesSinceOpen, kClose[GC], q, gc::kEdges, gc::kMu, gc::kSd, gc::kBL, gc::kBH);
    case HG: return timingT<hg::kJ, hg::kTB, 39, 64>(f, side, nowMinuteOfDay, minutesSinceOpen, kClose[HG], q, hg::kEdges, hg::kMu, hg::kSd, hg::kBL, hg::kBH);
    case NG: return timingT<ng::kJ, ng::kTB, 39, 65>(f, side, nowMinuteOfDay, minutesSinceOpen, kClose[NG], q, ng::kEdges, ng::kMu, ng::kSd, ng::kBL, ng::kBH);
    case EU: return timingT<eu::kJ, eu::kTB, 42, 70>(f, side, nowMinuteOfDay, minutesSinceOpen, kClose[EU], q, eu::kEdges, eu::kMu, eu::kSd, eu::kBL, eu::kBH);
  }
  Timing t; t.valid = false; t.pLater = t.pClose = t.elseMass = NAN; t.elseFrom = t.elseTo = -1; return t;
}
// FOMC days: the 1:00 PM statement resets the day (IN calls >= 80% were right 53-85% before 1 PM vs 95-96% normally)
inline bool fomcPause(int market, bool fomcDay, int nowMinuteOfDay) {
  if (!fomcDay) return false;
  switch (market) { case ES: return nowMinuteOfDay < es::kFomcPause; case NQ: return nowMinuteOfDay < nq::kFomcPause; case CL: return nowMinuteOfDay < cl::kFomcPause; case GC: return nowMinuteOfDay < gc::kFomcPause; case HG: return nowMinuteOfDay < hg::kFomcPause; case NG: return nowMinuteOfDay < ng::kFomcPause; case EU: return nowMinuteOfDay < eu::kFomcPause; }
  return false;
}
inline const char* version(int market) {
  switch (market) { case ES: return es::kVersion; case NQ: return nq::kVersion; case CL: return cl::kVersion; case GC: return gc::kVersion; case HG: return hg::kVersion; case NG: return ng::kVersion; case EU: return eu::kVersion; }
  return "?";
}
// ---- the step-by-step chain (table v15: 1st Time | Reclaim | 2nd Time) -------------------------------------------
// stage1(m)                      1st extreme window from the open: "8:30-9:00" (shown as centre ± half), side 'either'
// stage2(m, t1, depthAtr)        once the 1st extreme is IN: reclaim (first later close back through the RTH open)
//                                within [t1, t1 + w] with P >= kThr2   -> "8:51 - 9:21  76%"; depthAtr = |open - 1st| / ATR
// stage3(m, t1, reclaim)         once reclaimed: the latest T on the 15-min grid (>= the reclaim) with
//                                P(2nd extreme after T) >= kThr3       -> "after 11:00 83%"; gapMin = median 1st -> 2nd
// DISPLAY the calibrated %: <mkt>_ch::kShow2 / kShow3 (and <mkt>::kAfterShow) = how often that call was right on the
// last 60 sessions.  The raw cell P (afterP, p) ran 5-19 points hot in ES / NQ / GC on recent days.
// Stage 1's window [kS1From, kS1To] is calibrated so it DELIVERED ~60% on recent sessions (kS1P = its nominal share).
